import numpy as np

def generate_dinner_group(num_people):
    if num_people < 1:
        raise ValueError("Number of people must be at least 1")
    elif num_people > 100:
        raise ValueError("Number of people cannot exceed 100")

    dinner_group = np.random.choice([' Mozart', ' Einstein', ' Bill Gates', ' Marie Curie'], num_people)
    return dinner_group

